SET NAMES utf8mb4;

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'درمان ایمپلنت',
'<p>وقتی دندانی از دست می‌رود، فضای خالی در دهان دست‌نخورده نمی‌ماند. دندان‌های مجاور به‌مرور به سمت فضا متمایل می‌شوند، دندان مقابل ممکن است بلند شود و بار جویدن به‌صورت نامتوازن بر دندان‌های باقی‌مانده وارد می‌شود. استخوان فک در ناحیهٔ فضا نیز چون بار وارد بر آن از میان می‌رود، به‌مرور حجم از دست می‌دهد. از این رو جایگزینی دندان از دست‌رفته بیشتر اوقات انتخابی صرفاً ظاهری نیست.</p>
<p>ایمپلنت دندانی ریشهٔ مصنوعی‌ای است که به جای دندان از دست‌رفته در استخوان فک قرار می‌گیرد. روی آن می‌توان یک روکش تکی، بریجی که چند دندان را نگه می‌دارد یا پروتزی ثابت برای کل فک ساخت. کار ایمپلنت آن است که جای ریشهٔ از دست‌رفته را بگیرد و پروتز را از استخوان پشتیبانی کند.</p>
<h2>هر دندان از دست‌رفته با ایمپلنت جایگزین نمی‌شود</h2>
<p>ایمپلنت تنها گزینهٔ درمان دندان از دست‌رفته نیست. بریج متکی بر دندان، پروتز پارسیل متحرک و در برخی موارد بستن فضا با ارتودنسی نیز قابل ارزیابی‌اند. اینکه کدام گزینه مناسب است با ارزیابی هم‌زمان جایگاه و اندازهٔ فضا، وضعیت دندان‌های مجاور، حجم و کیفیت استخوان فک، سلامت لثه، رابطهٔ اکلوژن، وضعیت عمومی سلامت و عادت‌های مراقبت روزانه تعیین می‌شود.</p>
<p>این ارزیابی با معاینه، روش‌های تصویربرداری لازم و برنامه‌ریزی پروتتیک انجام می‌شود. اطلاع قطعی دربارهٔ تناسب که از طریق تلفن، پیام یا از روی عکس داده شود قابل اتکا نیست.</p>
<h2>درمان یک اقدام نیست، یک روند است</h2>
<p>درمان ایمپلنت به‌طور کلی از این مراحل تشکیل می‌شود: معاینه و تصویربرداری، تدوین برنامهٔ درمان، اقدامات آماده‌سازی در صورت نیاز، قرار دادن ایمپلنت، دورهٔ بهبودی لازم برای یکپارچه‌شدن ایمپلنت با استخوان، ساخت پروتز و معاینات منظم.</p>
<p>مدت این مراحل از فردی به فرد دیگر به‌روشنی متفاوت است. موردی که حجم استخوان کافی دارد با موردی که نیازمند پیوند استخوان است در یک تقویم پیش نمی‌رود. از این رو تعهدی به مدت ثابت داده نمی‌شود؛ مراحل تقریبی پس از معاینه ارائه می‌گردد.</p>
<h2>نتیجهٔ بلندمدت را یک عامل تعیین نمی‌کند</h2>
<p>کارکرد ایمپلنت در سال‌های طولانی به انتخاب درست مورد، برنامه‌ریزی، اجرای جراحی و پروتتیک، بهداشت دهان فرد، مصرف سیگار، وضعیت عمومی سلامت و معاینات منظم بستگی دارد. اگر یکی از این عوامل نادیده بماند نتیجه می‌تواند آسیب ببیند. بافت‌های پیرامون ایمپلنت نیز مانند دندان‌های طبیعی می‌توانند دچار التهاب شوند؛ بنابراین با پایان درمان، مراقبت پایان نمی‌یابد.</p>
<h2>پیش از ایمپلنت به چه نگاه می‌شود؟</h2>
<p>در معاینه تنها به ناحیهٔ دندان از دست‌رفته نگاه نمی‌شود. وضعیت دندان‌های باقی‌مانده، سلامت لثه، رابطهٔ اکلوژن و در صورت وجود عادت دندان‌قروچه ارزیابی می‌شود. اگر بیماری لثه ادامه داشته باشد پیش از ایمپلنت درمان می‌شود؛ زیرا بافت‌های پیرامون ایمپلنت نیز از همان پلاک میکروبی اثر می‌پذیرند.</p>
<p>سابقهٔ پزشکی نیز بخشی از برنامه‌ریزی است. دیابت کنترل‌نشده، برخی داروهای مؤثر بر متابولیسم استخوان، اختلالات خون‌ریزی، پرتودرمانی پیشین و مصرف سیگار از موضوعاتی‌اند که می‌توانند بر بهبودی اثر بگذارند. هیچ‌یک از این‌ها به‌تنهایی مانع قطعی نیست؛ اما می‌توانند برنامه‌ریزی و روند مورد انتظار را تغییر دهند. از این رو مهم است در نخستین گفت‌وگو داروهای مصرفی و بیماری‌های شناخته‌شدهٔ خود را بیان کنید.</p>
<h2>پروتز پس از ایمپلنت اندیشیده نمی‌شود</h2>
<p>یک برداشت نادرست رایج آن است که نخست ایمپلنت گذاشته شود و دندانی که روی آن ساخته می‌شود بعداً برنامه‌ریزی گردد. حال آنکه ترتیب برعکس است: نخست تعیین می‌شود کدام دندان، به چه شکل و در کجا ساخته خواهد شد؛ جایگاه و زاویهٔ ایمپلنت بر پایهٔ همین برنامه انتخاب می‌شود. به این کار برنامه‌ریزی هدایت‌شده با پروتز گفته می‌شود.</p>
<p>معنای عملی این رویکرد چنین است: ایمپلنتی که در جای نادرست قرار گرفته باشد حتی اگر بدون مشکل با استخوان یکپارچه شود، ممکن است نتوان روی آن دندانی درست، قابل تمیزکردن و زیبا ساخت. از این رو مرحلهٔ برنامه‌ریزی کم‌اهمیت‌تر از مرحلهٔ جراحی نیست.</p>
<h2>صفحه‌های این بخش</h2>
<h3>در آغاز درمان ایمپلنت</h3>
<ul>
<li><a href="/fa/dental-implant-tedavisi/">ایمپلنت دندانی</a> — کارکرد ایمپلنت، برای چه کسانی قابل ارزیابی است، مراحل درمان و دورهٔ بهبودی.</li>
<li>گزینه‌های درمان دندان از دست‌رفته — تفاوت میان ایمپلنت، بریج و پروتز متحرک. <em>(در دست تهیه)</em></li>
<li>برنامهٔ درمان ایمپلنت و گسترهٔ آن — چه چیزی برنامهٔ درمان را تعیین می‌کند. <em>(در دست تهیه)</em></li>
<li>پس از کشیدن دندان، ایمپلنت چه زمانی؟ — معیارهایی که زمان‌بندی را تعیین می‌کنند. <em>(در دست تهیه)</em></li>
</ul>
<h3>اگر استخوان کافی نباشد</h3>
<ul>
<li>پیوند استخوان و افزایش حجم استخوان — روش‌هایی که در کمبود حجم استخوان ارزیابی می‌شوند. <em>(در دست تهیه)</em></li>
<li>لیفت سینوس — رویکردی که در محدودبودن ارتفاع استخوان در ناحیهٔ خلفی فک بالا به کار می‌رود. <em>(در دست تهیه)</em></li>
</ul>
<h3>پروتز روی ایمپلنت</h3>
<ul>
<li>پروتزهای ثابت روی ایمپلنت — گزینه‌های روکش تکی، بریج و پروتز ثابت کل فک. <em>(در دست تهیه)</em></li>
<li>All-on-4 و All-on-6 — پروتز ثابت کل فک با شمار محدودی ایمپلنت. <em>(در دست تهیه)</em></li>
</ul>
<h3>اقدام و بهبودی</h3>
<ul>
<li>آیا درمان ایمپلنت دردناک است؟ — بی‌حسی موضعی و دورهٔ بهبودی. <em>(در دست تهیه)</em></li>
<li>روزهای نخست پس از ایمپلنت — درد، ورم، خون‌ریزی، تغذیه و مراقبت. <em>(در دست تهیه)</em></li>
</ul>
<h3>مراقبت بلندمدت</h3>
<ul>
<li>ایمپلنت را چگونه تمیز کنیم؟ — روال تمیزکردن روزانه و مسواک بین‌دندانی. <em>(در دست تهیه)</em></li>
<li>ایمپلنت در سیگار و دیابت — اثر این دو عامل بر بهبودی. <em>(در دست تهیه)</em></li>
</ul>
<h3>اگر مشکلی پیش آید</h3>
<ul>
<li>چرا ایمپلنت نمی‌گیرد؟ — علت‌های از دست رفتن زودهنگام و دیرهنگام ایمپلنت. <em>(در دست تهیه)</em></li>
<li>پری‌ایمپلنتیت — التهاب و از دست رفتن استخوان پیرامون ایمپلنت. <em>(در دست تهیه)</em></li>
</ul>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا ایمپلنت برای همه قابل انجام است؟</strong><br>تناسب با ارزیابی هم‌زمان حجم و کیفیت استخوان فک، سلامت لثه، وضعیت عمومی سلامت، داروهای مصرفی، مصرف سیگار و بهداشت دهان تعیین می‌شود. بدون معاینه و تصویربرداری نمی‌توان تصمیم گرفت.</p>
<p><strong>از کجا آغاز کنم؟</strong><br>نخستین گام معاینه است. پس از ارزیابی هم‌زمان شکایت شما، یافته‌های داخل دهان و تصویربرداری لازم، گزینه‌ها و مراحل تقریبی با شما در میان گذاشته می‌شود.</p>
<p><strong>چند ایمپلنت لازم است؟</strong><br>شمار دندان‌های از دست‌رفته به‌تنهایی تعیین‌کننده نیست. توزیع استخوان، بار اکلوزال، نوع پروتز برنامه‌ریزی‌شده و نیاز زیبایی با هم ارزیابی می‌شوند. پیش از معاینه تعهدی به شمار داده نمی‌شود.</p>
<p><strong>آیا پس از ایمپلنت مراقبت ویژه‌ای لازم است؟</strong><br>بله. بافت‌های پیرامون ایمپلنت نیز می‌توانند دچار التهاب شوند. تمیزکردن روزانه، تمیزکردن بین‌دندانی و معاینات منظم مستقیماً بر نتیجهٔ بلندمدت اثر می‌گذارند.</p>
<p><strong>آیا سن من مانع ایمپلنت است؟</strong><br>حد بالای سنی وجود ندارد؛ آنچه تعیین‌کننده است نه سن بلکه پشتیبانی استخوان و لثه و وضعیت عمومی سلامت است. در حد پایین انتظار می‌رود رشد فک کامل شده باشد.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، تناسب ایمپلنت با ارزیابی هم‌زمان معاینهٔ بالینی، یافته‌های تصویربرداری لازم و برنامه‌ریزی پروتتیک تعیین می‌شود. در پایان ارزیابی، گزینه‌ها و مراحل تقریبی به‌صورت کتبی ارائه می‌گردد.</p>
<p><a href="/fa/agiz-cerrahisi-uygulamalari/">اقدامات جراحی دهان</a> · <a href="/fa/iletisim">نوبت و تماس</a></p>',
'درمان ایمپلنت چیست، برای چه کسانی قابل انجام است و از چه مراحلی تشکیل می‌شود؟ برنامه‌ریزی، جراحی، پروتز و مراقبت بلندمدت را اینجا بیابید.',
'درمان ایمپلنت | MSc. Dt. Mehmet Taş',
'FA' FROM pages WHERE link = 'implant';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'دندان‌پزشکی زیبایی',
'<p>دندان‌پزشکی زیبایی می‌کوشد رنگ، شکل و آرایش دندان‌ها را با چهره هماهنگ کند. اما بنیادی که این کار بر آن استوار می‌شود همواره سلامت دهان است. اگر پوسیدگی فعال، التهاب لثه، مشکل درمان‌نشدهٔ ریشه یا اکلوژن نامتوازن وجود داشته باشد، اقدام زیبایی بر روی آن‌ها بنا نمی‌شود؛ نخست این مشکل‌ها برطرف می‌شوند.</p>
<p>دلیل این کار تنها یک قاعده نیست. لبهٔ ترمیمی که کنار لثهٔ ملتهب ساخته شود می‌تواند به‌مرور آشکار شود و اگر عادت دندان‌قروچه نادیده بماند، سرامیک تازه زودتر از انتظار آسیب می‌بیند. از این رو برنامه‌ریزی زیبایی با معاینه آغاز می‌شود.</p>
<h2>یک روش برای همه مناسب نیست</h2>
<p>به دو نفری که با یک شکایت می‌آیند ممکن است درمان یکسانی پیشنهاد نشود. در دندانی که رنگش تیره شده گاه سفیدکردن کافی است و گاه علتی زمینه‌ای وجود دارد و راه‌حل ترمیمی لازم است. در بی‌نظمی کوچک شکل، باندینگ کافی است، در حالی که در از دست رفتن گستردهٔ بافت روکش مطرح می‌شود. در مشکلات آرایش دندان‌ها نیز ارزیابی ارتودنسی می‌تواند محافظه‌کارانه‌تر از اقدام ترمیمی باشد.</p>
<p>هنگام تصمیم‌گیری این موارد با هم ارزیابی می‌شوند: بافت سالم باقی‌ماندهٔ دندان، میزان مینا، جایگاه دندان در دهان، زمینهٔ رنگ، سطوح لثه، نیروی اکلوژن، عادت دندان‌قروچه و انتظار فرد. هدف رسیدن به نتیجه با محافظه‌کارانه‌ترین گزینهٔ ممکن است.</p>
<h2>ظاهر طبیعی چگونه برنامه‌ریزی می‌شود؟</h2>
<p>نتیجهٔ طبیعی نه از تک‌تک دندان‌ها بلکه از هماهنگی کل برمی‌آید. نسبت‌های دندان، بافت سطح، عبور نور، مسیر لبهٔ لثه، خط لبخند و رابطهٔ لب و دندان با هم در نظر گرفته می‌شوند. تنها سفیدکردن دندان‌ها یا ساختن همهٔ آن‌ها در یک اندازه ظاهر طبیعی نمی‌دهد؛ آنچه تعیین‌کننده است رابطه با دندان‌های مجاور و با چهره است.</p>
<p>لثه نیز بخشی از این کل است. میزان دیده‌شدن آن هنگام لبخند، تقارن سطوح و سلامت بافت به‌اندازهٔ دندان‌ها در طبیعی‌دیده‌شدن نتیجه مؤثرند.</p>
<h2>انتظارها و مرزها آشکارا گفته می‌شوند</h2>
<p>یکی از مهم‌ترین مراحل درمان زیبایی، بیان انتظار پیش از معاینه است. در موارد مناسب می‌توان با برنامه‌ریزی دیجیتال و پیش‌نمایش دربارهٔ نتیجهٔ احتمالی تصوری به دست آورد. پیش‌نمایش ابزاری برای برنامه‌ریزی است؛ تعهدی به نتیجهٔ عیناً یکسان نیست.</p>
<p>رفتار رنگی مواد سرامیکی و کامپوزیتی با دندان طبیعی تفاوت دارد: دندان طبیعی به‌مرور رنگ می‌بازد در حالی که ترمیم می‌تواند ثابت بماند. از این رو اگر سفیدکردن و ترمیم با هم برنامه‌ریزی شوند، ترتیب اهمیت دارد. به همین شکل برای هیچ ترمیمی نمی‌توان مدت کاربرد ثابتی اعلام کرد؛ نتیجه را به‌اندازهٔ انتخاب ماده، مراقبت، اکلوژن و معاینات تعیین می‌کنند.</p>
<h2>ترتیب، نتیجه را تغییر می‌دهد</h2>
<p>در درمان زیبایی، ترتیب اقدام‌ها به‌اندازهٔ خود اقدام اهمیت دارد. رویکرد کلی چنین است: نخست مشکل‌های سلامت دهان حل می‌شوند، سپس در صورت نیاز آرایش دندان‌ها سامان می‌یابد، پس از آن کار روی رنگ انجام می‌شود و در پایان اقدام‌های ترمیمی تکمیل می‌گردند.</p>
<p>دلیل این ترتیب عملی است. اگر قرار است دندان‌ها با ارتودنسی اصلاح شوند، روکش‌هایی که پیش از آن گذاشته شوند ممکن است با جایگاه تازه سازگار نباشند. اگر سفیدکردن برنامه‌ریزی شده باشد، ترمیم‌های ناحیهٔ دیدنی باید بر پایهٔ رنگ به‌دست‌آمده انتخاب شوند؛ زیرا سرامیک و کامپوزیت از سفیدکردن اثر نمی‌پذیرند.</p>
<h2>چه زمانی کمتر بهتر است؟</h2>
<p>در دندان‌پزشکی زیبایی بهترین نتیجه همیشه از گسترده‌ترین اقدام به دست نمی‌آید. بافت سالم مینا اگر یک بار برداشته شود بازنمی‌گردد؛ از این رو اگر بتوان به همان نتیجه از راهی محافظه‌کارانه‌تر رسید، همان راه ترجیح داده می‌شود.</p>
<p>برای نمونه: برای شکستگی کوچک در یک دندان می‌توان به‌جای روکش، باندینگ را ارزیابی کرد؛ در شکایت خفیف رنگ می‌توان به‌جای ترمیم به سفیدکردن بسنده کرد؛ فاصلهٔ میان دندان‌ها در برخی موارد با ارتودنسی بسته می‌شود. هر یک از این گزینه‌ها برای هر مورد مناسب نیست، اما باید در معاینه با هم ارزیابی شوند. اگر تنها یک گزینه به شما ارائه شود، حق دارید بپرسید چرا گزینه‌های دیگر مناسب نیستند.</p>
<h2>صفحه‌های این بخش</h2>
<h3>برنامه‌ریزی</h3>
<ul>
<li><a href="/fa/gulus-tasarimi/">طراحی لبخند فردی</a> — روند برنامه‌ریزی که در آن دندان، لثه، لب و نسبت‌های چهره با هم ارزیابی می‌شوند.</li>
<li>نسبت طلایی در طراحی لبخند — قواعد نسبت کجا به کار می‌آیند. <em>(در دست تهیه)</em></li>
<li>زیبایی صورتی و شکل‌دهی لثه — سطوح لثه و تقارن. <em>(در دست تهیه)</em></li>
</ul>
<h3>روکش‌ها و لمینت‌ها</h3>
<ul>
<li><a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> — حوزه‌های کاربرد، گردش کار دیجیتال، گزینه‌های ماده و مراقبت.</li>
<li>E.max و لمینت ونیر — تناسب در کاربردهای دی‌سیلیکات لیتیوم و لمینت. <em>(در دست تهیه)</em></li>
<li>لمینت یا زیرکونیا؟ — مقایسهٔ دو گزینه. <em>(در دست تهیه)</em></li>
</ul>
<h3>گزینه‌های محافظه‌کارانه‌تر</h3>
<ul>
<li>باندینگ و ترمیم کامپوزیت زیبایی — رویکرد محافظه‌کارانه در اصلاح محدود شکل و رنگ. <em>(در دست تهیه)</em></li>
<li><a href="/fa/dis-beyazlatma/">سفیدکردن دندان</a> — روش‌های کلینیکی، خانگی و ترکیبی؛ مدیریت حساسیت.</li>
</ul>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>از کجا آغاز کنم، به چه درمانی نیاز دارم؟</strong><br>نقطهٔ آغاز ارزیابی طراحی لبخند است. پس از بررسی هم‌زمان انتظار شما، یافته‌های سلامت دهان و اکلوژن، توضیح داده می‌شود کدام اقدام‌ها مناسب‌اند و آیا گزینهٔ محافظه‌کارانه‌تری وجود دارد.</p>
<p><strong>آیا تراش دندان‌هایم ضروری است؟</strong><br>خیر. در برخی موارد گزینه‌هایی که تراش نمی‌خواهند مانند سفیدکردن یا باندینگ کافی‌اند. میزان آماده‌سازی بر پایهٔ ساختار کنونی دندان و ترمیم انتخاب‌شده تغییر می‌کند.</p>
<p><strong>نخست سفیدکردن یا روکش؟</strong><br>اگر سفیدکردن دندان‌های طبیعی برنامه‌ریزی شده باشد، ترمیم‌های ناحیهٔ دیدنی معمولاً پس از سفیدکردن و بر پایهٔ رنگ به‌دست‌آمده ساخته می‌شوند. مواد ترمیمی مانند دندان طبیعی تغییر رنگ نمی‌دهند.</p>
<p><strong>نتیجه چقدر دوام می‌آورد؟</strong><br>مدت ثابتی نمی‌توان اعلام کرد. انتخاب ماده، بافت باقی‌مانده، بار اکلوزال، عادت دندان‌قروچه، بهداشت دهان و معاینات منظم بر نتیجه اثر می‌گذارند.</p>
<p><strong>دندان‌هایم را می‌فشارم، آیا اقدام زیبایی ممکن است؟</strong><br>عادت فشردن و سایش بر برنامه‌ریزی اثر می‌گذارد و نخست ارزیابی می‌شود. در صورت لزوم نایت‌گارد محافظ بخشی از برنامه می‌شود.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، گزینه‌های درمان زیبایی همراه با سلامت دهان، حفظ بافت دندان، رابطهٔ اکلوژن و هدف ظاهر طبیعی ارزیابی می‌شوند.</p>
<p><a href="/fa/iletisim">نوبت و تماس</a></p>',
'طراحی لبخند، زیرکونیا، لمینت، باندینگ و سفیدکردن؛ اینجا ببینید در هر وضعیت کدام گزینه ارزیابی می‌شود.',
'دندان‌پزشکی زیبایی | MSc. Dt. Mehmet Taş',
'FA' FROM pages WHERE link = 'estetik';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'سلامت دهان و دندان',
'<p>برای مراجعه به دندان‌پزشک بیشتر اوقات منتظر درد می‌مانند. حال آنکه درد در بسیاری از موارد نه آغاز روند بلکه مرحلهٔ پیشرفتهٔ آن است. پوسیدگی وقتی در مینا آغاز می‌شود درد ندارد؛ ژنژیویت که مرحلهٔ زودهنگام بیماری لثه است ممکن است جز خون‌ریزی نشانه‌ای ندهد. از این رو معاینهٔ منظم امکان می‌دهد درمان با مداخله‌ای کوچک‌تر و با از دست رفتن کمتر بافت کامل شود.</p>
<p>این بخش جاهایی را در بر می‌گیرد که سلامت دهان و دندان با زندگی روزمره تلاقی می‌کند: پوسیدگی و ترمیم، مشکلات لثه، درد و وضعیت‌های اورژانسی، حساسیت، شکایت‌های فک و عضله، عادت‌های مراقبت روزانه و سلامت دندان کودکان.</p>
<h2>دهان از بقیهٔ بدن جدا نیست</h2>
<p>رابطهٔ بیماری لثه و دیابت دوسویه است: قند خون کنترل‌نشده می‌تواند بر بافت لثه اثر بگذارد، در حالی که التهاب پیوستهٔ لثه نیز کنترل قند را دشوار می‌کند. به همین شکل تغییرات هورمونی در بارداری می‌تواند لثه را نسبت به پلاک حساس‌تر کند. برخی داروها با ایجاد خشکی دهان خطر پوسیدگی را افزایش می‌دهند.</p>
<p>از این رو در معاینه تنها به دندان‌ها نگاه نمی‌شود. سابقهٔ پزشکی، داروهای مصرفی و بیماری‌های زمینه‌ای در صورت وجود بخشی از برنامه‌ریزی‌اند. در صورت نیاز با پزشک مربوط هماهنگی برقرار می‌شود.</p>
<h2>مراقبت روزانه ادامهٔ درمان است</h2>
<p>هیچ اقدامی که در کلینیک انجام شود جای مراقبت در خانه را نمی‌گیرد. اگر پس از جرم‌گیری تجمع پلاک ادامه یابد التهاب لثه بازمی‌گردد؛ اگر در دهانی که ترمیم شده خطر پوسیدگی مدیریت نشود پوسیدگی‌های تازه پدید می‌آیند. بنابراین شیوهٔ مسواک‌زدن، تمیزکردن بین دندان‌ها، انتخاب خمیردندان و نظم تغذیه به‌اندازهٔ درمان اهمیت دارند.</p>
<p>ابزار درست برای همه یکسان نیست. پهنای فاصله‌های بین‌دندانی، وجود پروتز یا ایمپلنت، مهارت دست و عادت‌ها می‌توانند ابزارهای متفاوتی بطلبند.</p>
<h2>در درد و وضعیت‌های اورژانسی انتظار زیان‌بار است</h2>
<p>درد شدید دندان، ورم صورت، تب، شکستگی پس از ضربه یا دندانی که از جا درآمده وضعیت‌هایی‌اند که نباید به تعویق افتند. به‌ویژه در دندان دائمی که از جا درآمده، دقیقه‌های نخست تعیین‌کننده‌اند. ضربه به دندان در کودکان نیز بر پایهٔ تفکیک دندان شیری و دائمی رویکردی به‌کلی متفاوت می‌طلبد.</p>
<h2>خطی که درمان را از پیشگیری جدا می‌کند</h2>
<p>بیشتر اقدام‌هایی که در دندان‌پزشکی انجام می‌شود جای بافتی از دست‌رفته را پر می‌کند. ترمیم جای بافت پوسیده را می‌گیرد، روکش دندان شکسته را در بر می‌گیرد. اما هیچ‌یک عیناً جای بافت طبیعی را نمی‌گیرد و هیچ‌یک برای همیشه نمی‌ماند. از این رو سود اصلی در دندان‌پزشکی بیش از آنکه از کیفیت اقدام بیاید، از آن می‌آید که اصلاً نیازی به آن اقدام پدید نیاید.</p>
<p>پیشگیری از چیزهای ملموس ساخته می‌شود: شیوهٔ درست مسواک‌زدن، تمیزکردن بین دندان‌ها، کاهش تکرار مصرف قند، بهره‌گیری از فلوراید و مراجعه برای معاینه در فاصله‌های متناسب با سطح خطر. این‌ها ساده به نظر می‌رسند اما اثرشان انباشتی است.</p>
<h2>چرا رویکرد در کودکان متفاوت است؟</h2>
<p>دندان‌پزشکی کودکان نسخهٔ کوچک‌شدهٔ درمان بزرگ‌سالان نیست. مینای دندان شیری نازک‌تر است و پوسیدگی می‌تواند سریع‌تر پیش برود. دندان شیری که زودهنگام از دست برود می‌تواند جای در نظر گرفته‌شده برای دندان دائمی زیرین را تنگ کند. در ضربه نیز دندان شیری و دائمی به‌کلی متفاوت اداره می‌شوند؛ دندان شیری اگر از جا درآید دوباره جاگذاری نمی‌شود.</p>
<p>افزون بر این، موفقیت درمان در کودک به رابطه‌ای که او با این روند برقرار می‌کند نیز بستگی دارد. کودکی که در دوره‌ای بدون درد با کلینیک آشنا شده باشد، درمان لازم در آینده معمولاً آسان‌تر اداره می‌شود. از این رو هدف نخستین مراجعه معمولاً درمان نیست.</p>
<h2>صفحه‌های این بخش</h2>
<h3>پوسیدگی، ترمیم و ریشه</h3>
<ul>
<li><a href="/fa/kanal-tedavisi/">درمان ریشه</a> — در چه وضعیتی انجام می‌شود، مراحل آن و ترمیم پس از آن.</li>
<li><a href="/fa/dis-curugu-kompozit-dolgu/">پوسیدگی دندان و ترمیم کامپوزیت</a> — چگونه پوسیدگی را تشخیص دهیم و گزینه‌های درمان.</li>
</ul>
<h3>گام نخست و معاینه</h3>
<ul>
<li><a href="/fa/ilk-dis-muayenesi-tedavi-planlamasi/">نخستین معاینه و برنامه‌ریزی درمان</a> — در معاینه چه ارزیابی می‌شود.</li>
<li>معاینهٔ منظم — عواملی که فاصلهٔ معاینه را تعیین می‌کنند. <em>(در دست تهیه)</em></li>
<li>ترس از دندان‌پزشک — رویکرد درمان در بیماران مضطرب. <em>(در دست تهیه)</em></li>
</ul>
<h3>لثه</h3>
<ul>
<li>جرم‌گیری و سلامت لثه — جرم چگونه شکل می‌گیرد و تمیزکردن چه را در بر می‌گیرد. <em>(در دست تهیه)</em></li>
<li>بیماری‌های لثه — تفاوت ژنژیویت و پریودنتیت. <em>(در دست تهیه)</em></li>
</ul>
<h3>درد، حساسیت و اورژانس</h3>
<ul>
<li>درد اورژانسی دندان — چه زمانی نباید منتظر ماند و نخست چه باید کرد. <em>(در دست تهیه)</em></li>
<li>حساسیت دندان — علت‌های حساسیت به سرد و گرم. <em>(در دست تهیه)</em></li>
</ul>
<h3>کودکان و دوره‌های ویژه</h3>
<ul>
<li><a href="/fa/cocuk-dis-hekimligi/">دندان‌پزشکی کودکان</a> — سن نخستین معاینه، پوسیدگی دندان شیری، فلوراید.</li>
<li><a href="/fa/hamilelikte-dis-tedavisi/">درمان دندان در بارداری</a> — برنامه‌ریزی بر پایهٔ دوره‌ها و مراقبت در خانه.</li>
<li><a href="/fa/cocuklarda-dis-travmasi/">ضربه به دندان در کودکان</a> — سی دقیقهٔ نخست در دندان شکسته یا از جا درآمده.</li>
</ul>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>هر چند وقت یک بار برای معاینه بیایم؟</strong><br>فاصلهٔ یکسانی برای همه وجود ندارد. با ارزیابی خطر پوسیدگی، وضعیت لثه، بهداشت دهان، مصرف سیگار و بیماری‌های زمینه‌ای فاصله‌ای ویژهٔ شما تعیین می‌شود.</p>
<p><strong>درد ندارم، آیا باز هم معاینه لازم است؟</strong><br>بله. مرحلهٔ زودهنگام پوسیدگی و آغاز بیماری لثه بیشتر اوقات درد ندارند. مشکلی که زود تشخیص داده شود با اقدامی کوچک‌تر درمان می‌شود.</p>
<p><strong>لثه‌ام هنگام مسواک‌زدن خون‌ریزی می‌کند، آیا مسواک را کنار بگذارم؟</strong><br>خیر. در بیشتر وضعیت‌های مرتبط با پلاک، کنارگذاشتن تمیزکردن التهاب را افزایش می‌دهد. باید با مسواک نرم، تمیزکردن ملایم و منظم را ادامه داد و برای معاینه نوبت گرفت.</p>
<p><strong>کودکم را نخستین بار چه زمانی بیاورم؟</strong><br>در شش ماه پس از رویش نخستین دندان شیری و دیرترین هنگام در نخستین سالگرد توصیه می‌شود. هدف این مراجعه بیشتر اوقات درمان نیست، بلکه ارزیابی خطر و آشناشدن است.</p>
<p><strong>کدام خمیردندان را به کار ببرم؟</strong><br>انتخاب بر پایهٔ سن، خطر پوسیدگی، حساسیت و وضعیت لثه تغییر می‌کند. آنچه برای شما مناسب است در معاینه توضیح داده می‌شود.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، ارزیابی سلامت دهان و دندان با در نظر گرفتن هم‌زمان شکایت‌ها، یافته‌های داخل دهان و تصویربرداری لازم انجام می‌شود؛ و فاصلهٔ مراقبت و معاینهٔ ویژهٔ شما تعیین می‌گردد.</p>
<p><a href="/fa/iletisim">نوبت و تماس</a></p>',
'پوسیدگی، لثه، درد دندان، حساسیت، مراقبت روزانه و سلامت دندان کودکان؛ از معاینه تا درمان پیشگیرانه را اینجا بیابید.',
'سلامت دهان و دندان | MSc. Dt. Mehmet Taş',
'FA' FROM pages WHERE link = 'agiz-dis-sagligi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'جراحی دهان و فک',
'<p>اقدام‌های جراحی دهان نیازمند ارزیابی هم‌زمان دندان، استخوان فک و ساختارهای پیرامون است. جایگاه دندان، شکل ریشه، رابطهٔ آن با استخوان و ساختارهای تشریحی مجاور تنها با معاینهٔ بالینی و روش‌های مناسب تصویربرداری آشکار می‌شوند. از این رو اقدام جراحی با نگاه‌کردن به دهان و گفتن «باید کشیده شود» برنامه‌ریزی نمی‌گردد.</p>
<p>در فک پایین رابطهٔ ریشه‌های دندان با کانال فک پایین و در فک بالا مجاورت دندان‌ها با حفرهٔ سینوس مستقیماً بر برنامه‌ریزی اثر می‌گذارد. این روابط در برخی موارد با رادیوگرافی پانورامیک و در برخی با تصویربرداری سه‌بعدی ارزیابی می‌شوند.</p>
<h2>هر دندان نهفته کشیده نمی‌شود</h2>
<p>دندان‌های عقل وقتی در دهان جا نمی‌یابند ممکن است نیمه‌رویش کنند یا درون استخوان نهفته بمانند. این همواره به کشیدن نمی‌انجامد. کشیدن در وضعیت‌هایی مانند درد، عفونت مکرر، آسیب به دندان مجاور، گمان به تشکیل کیست، جایگاه غیرقابل تمیزکردن یا نیاز درمانی دیگری که برنامه‌ریزی شده ارزیابی می‌شود. در دندان‌هایی که شکایتی ایجاد نمی‌کنند و قابل پیگیری‌اند ممکن است مشاهده ترجیح داده شود.</p>
<p>همین رویکرد دربارهٔ کشیدن جراحی نیز صادق است: نخست امکان نجات دندان ارزیابی می‌شود. در مواردی که با درمان ریشه، جراحی نوک ریشه یا راه‌حلی ترمیمی می‌توان دندان را در دهان نگه داشت، کشیدن نخستین گزینه نیست.</p>
<h2>خطرها از آغاز توضیح داده می‌شوند</h2>
<p>ورم، حساسیت، محدودیت بازشدن دهان و دشواری در جویدن پس از اقدام‌های جراحی یافته‌هایی مورد انتظارند. این‌ها عارضه نیستند بلکه بخشی عادی از بهبودی‌اند و معمولاً در روزهای نخست آشکارترند. افزون بر این هر اقدامی خطرهای ویژهٔ خود را دارد؛ خطرهای وابسته به مجاورت تشریحی، خون‌ریزی، عفونت و پیشرفت کندتر از انتظار بهبودی از آن جمله‌اند.</p>
<p>توضیح این خطرها به‌صورت فردی بخشی از اقدام است. اینکه کدام یافته‌ها مورد انتظارند و کدام‌یک مراجعهٔ بی‌درنگ می‌طلبند، پیش و پس از اقدام بیان می‌شود.</p>
<h2>حجم استخوان بخشی از برنامه‌ریزی ایمپلنت است</h2>
<p>بخش مهمی از جراحی دهان با درمان ایمپلنت درهم‌تنیده است. اگر دندان مدت‌ها پیش از دست رفته باشد، حجم استخوان آن ناحیه ممکن است کاهش یافته باشد. در چنین مواردی پیش از ایمپلنت افزایش حجم استخوان یا بالابردن کف سینوس در ناحیهٔ خلفی فک بالا مطرح می‌شود. این برای هر بیمار لازم نیست؛ نیاز با ارزیابی هم‌زمان تصویربرداری و برنامهٔ پروتتیک تعیین می‌گردد.</p>
<h2>روند برنامه‌ریزی آشکارا بیان می‌شود</h2>
<p>گستره و شرایط اجرای هر اقدام جراحی متفاوت است. در پایان ارزیابی تعیین می‌شود که اقدام در چه شرایطی و با کدام تیم مناسب است؛ این برنامه‌ریزی آشکارا برای بیمار توضیح داده می‌شود و روند با هم به تصمیم می‌رسد.</p>
<p>MSc. Dt. Mehmet Taş پس از تحصیل در دانشکدهٔ دندان‌پزشکی دانشگاه استانبول، کارشناسی ارشد خود را در ایتالیا در رشتهٔ جراحی دهان و ایمپلنتولوژی به پایان رسانده است. این تحصیل عنوان تخصص نیست؛ بنیاد علمی رویکردی را می‌سازد که در برنامه‌ریزی جراحی و ایمپلنت دنبال می‌شود.</p>
<h2>آماده‌سازی پیش از اقدام</h2>
<p>اطلاعاتی هست که باید پیش از هر اقدام جراحی بیان شود: بیماری‌های شناخته‌شده، داروهای مصرفی منظم، حساسیت‌ها، جراحی‌های پیشین و در صورت وجود وضعیتی مرتبط با خون‌ریزی. داروهای رقیق‌کنندهٔ خون، داروهای مؤثر بر متابولیسم استخوان و درمان‌های سرکوب‌کنندهٔ ایمنی مستقیماً بر برنامه‌ریزی اثر می‌گذارند.</p>
<p>این داروها نباید بدون توصیهٔ پزشک قطع شوند. در موارد لازم با هماهنگی پزشک مربوط، زمان و روش اقدام بر همان پایه تعیین می‌شود.</p>
<h2>در دورهٔ بهبودی چه انتظاری داشته باشیم؟</h2>
<p>روزهای نخست بهبودی متفاوت از هفته‌های بعد پیش می‌روند. بیست‌وچهار ساعت نخست از نظر محافظت از لخته اهمیت دارد: توصیه می‌شود ناحیه تحت فشار قرار نگیرد، دهان به‌شدت شسته نشود، با نی نوشیده نشود و از سیگار پرهیز گردد. ورم معمولاً در روزهای نخست بیشتر می‌شود و سپس کاهش می‌یابد. محدودیت موقت در بازشدن دهان ممکن است پدید آید.</p>
<p>این‌ها یافته‌های مورد انتظارند. در مقابل، درد فزاینده‌ای که برطرف نمی‌شود، تب بالا، ورم گسترده، بوی بد یا ترشح، دشواری در بلع یا تنفس مراجعهٔ بی‌درنگ می‌طلبند.</p>
<h2>صفحه‌های این بخش</h2>
<ul>
<li><a href="/fa/agiz-cerrahisi-uygulamalari/">اقدامات جراحی دهان</a> — گستره، ارزیابی پیش از اقدام، بهبودی و توضیح خطرها.</li>
<li>دندان عقل نهفته — در چه وضعیتی کشیدن ارزیابی می‌شود و در چه وضعیتی مشاهده. <em>(در دست تهیه)</em></li>
<li>پیوند استخوان و افزایش حجم استخوان — روش‌ها و بهبودی در کمبود استخوان. <em>(در دست تهیه)</em></li>
<li>لیفت سینوس — رویکردی که در محدودبودن ارتفاع استخوان در ناحیهٔ خلفی فک بالا به کار می‌رود. <em>(در دست تهیه)</em></li>
</ul>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>دندان عقلم درد نمی‌کند، آیا باز هم آن را بکشم؟</strong><br>اگر شکایتی نباشد کشیدن خودبه‌خود لازم نیست. با ارزیابی جایگاه دندان، امکان تمیزکردن آن، اثرش بر دندان مجاور و یافته‌های رادیوگرافیک تصمیم گرفته می‌شود که کشیدن مناسب است یا مشاهده.</p>
<p><strong>آیا در حین اقدام درد احساس می‌شود؟</strong><br>اقدام زیر بی‌حسی موضعی انجام می‌شود و راحتی هدف است. احساس فشار و لرزش ممکن است باشد. چون تجربهٔ فردی می‌تواند متفاوت باشد، تضمین قطعی بی‌دردی داده نمی‌شود.</p>
<p><strong>ورم چقدر طول می‌کشد؟</strong><br>ورم معمولاً در روزهای نخست آشکار است و کاهش‌یابنده برطرف می‌شود. مدت بر پایهٔ گستردگی اقدام و فرد تغییر می‌کند. در درد فزاینده، تب یا ورم گسترده باید بی‌درنگ مراجعه کرد.</p>
<p><strong>داروی رقیق‌کنندهٔ خون مصرف می‌کنم، آیا اقدام ممکن است؟</strong><br>داروهای مصرفی خود را اعلام کنید. داروهای رقیق‌کنندهٔ خون نباید بدون توصیهٔ پزشک قطع شوند؛ در موارد لازم با پزشک مربوط برنامه‌ریزی می‌شود.</p>
<p><strong>آیا در هر ایمپلنت پیوند استخوان لازم است؟</strong><br>خیر. نیاز با ارزیابی هم‌زمان حجم استخوان موجود و پروتز برنامه‌ریزی‌شده تعیین می‌شود؛ در بیشتر موارد اقدام افزوده لازم نیست.</p>
<p><strong>آیا پس از اقدام می‌توانم به کار یا مدرسه بروم؟</strong><br>بر پایهٔ گستردگی اقدام تغییر می‌کند. در روز نخست استراحت توصیه می‌شود. توصیه‌های ویژهٔ شما پیش از اقدام ارائه می‌گردد.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، نیاز جراحی با ارزیابی هم‌زمان معاینهٔ بالینی، روش‌های تصویربرداری لازم و مجاورت‌های تشریحی تعیین می‌شود. در پایان ارزیابی، برنامهٔ درمان مناسب با بیمار تعیین می‌گردد.</p>
